SELECT i.i_item_sk, i.i_brand, i.i_category, COUNT(ss.ss_ticket_number) AS sales_transactions, AVG(ss.ss_ext_sales_price) AS avg_sale_price, SUM(ss.ss_ext_sales_price) AS total_sales, SUM(ss.ss_ext_tax) AS total_tax, SUM(ss.ss_net_profit) AS total_profit, SUM(CASE WHEN p.p_discount_active = 'Y' THEN ss.ss_ext_sales_price * 0.15 ELSE 0 END) AS promo_discount_estimate, ROW_NUMBER() OVER (ORDER BY SUM(ss.ss_net_profit) DESC) AS profit_rank FROM item i LEFT JOIN store_sales ss ON ss.ss_item_sk = i.i_item_sk LEFT JOIN promotion p ON p.p_item_sk = i.i_item_sk WHERE i.i_current_price > 20 AND i.i_category = 'Electronics' GROUP BY i.i_item_sk, i.i_brand, i.i_category HAVING SUM(ss.ss_ext_sales_price) > 1000 ORDER BY profit_rank DESC LIMIT 10
